import{_ as t,c as o,o as s,ae as l}from"./chunks/framework.Bi6zybwU.js";const d=JSON.parse('{"title":"Hyperlinks from Google Sheets","description":"Hyperlinks from Google Sheets","frontmatter":{"title":"Hyperlinks from Google Sheets","description":"Hyperlinks from Google Sheets"},"headers":[],"relativePath":"guide/table-formatting/hyperlinks-from-google-sheets.md","filePath":"guide/table-formatting/hyperlinks-from-google-sheets.md"}'),a={name:"guide/table-formatting/hyperlinks-from-google-sheets.md"};function n(i,e,r,h,p,g){return s(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="hyperlinks-from-google-sheets" tabindex="-1">Hyperlinks from Google Sheets <a class="header-anchor" href="#hyperlinks-from-google-sheets" aria-label="Permalink to &quot;Hyperlinks from Google Sheets&quot;">​</a></h1><p>Consider a user who has a data table in Google Sheets and wishes to import the table from <strong>Google</strong> <strong>Sheets</strong> to Ninja Tables. If the table contains hyperlinks, he would want the links to work in Ninja Tables as well. But if the hyperlink is erased after the table is imported, the table does not serve its purpose. This is because the hyperlinked data cannot be saved after the table is converted to CSV. <strong>But Ninja Tables will bring the links back just by changing the data type!</strong></p><h2 id="html-data-type-for-hyperlink-from-google-sheets" tabindex="-1">HTML Data Type for Hyperlink from Google Sheets <a class="header-anchor" href="#html-data-type-for-hyperlink-from-google-sheets" aria-label="Permalink to &quot;HTML Data Type for Hyperlink from Google Sheets&quot;">​</a></h2><p>This short guide will demonstrate to you how to include hyperlinked data in your table when it&#39;s imported from Google Sheets.</p><ul><li>For instance, we&#39;ve imported a Google Sheet with three columns named <strong>Title</strong>, <strong>Link Text, <strong>and</strong> Actual link</strong>. This is a dummy table containing information about different mobile phone models. <img src="https://ninjatables.com/wp-content/uploads/2022/11/image-3.png" alt="Change Column Data Type for Hyperlinks"> When you create a &quot;Google Sheets data table&quot; with this sheet, the column with links will initially remove the links and keep the texts. <img src="https://ninjatables.com/wp-content/uploads/2022/11/Links-in-Google-Sheets-1024x409.png" alt="Removed links from Google Sheets"></li><li>The next step is to add the* *link to the link text column. Simply go to table column configuration and set the data type to &quot;<strong>HTML Field</strong>.&quot; <img src="https://ninjatables.com/wp-content/uploads/2022/10/HTML-Field.webp" alt="Change data type"></li><li>Update the column settings and check the table preview. <img src="https://ninjatables.com/wp-content/uploads/2022/11/clickable-links-from-Google-Sheets-1024x329.png" alt="Clickable links from Google Sheets"> Now the links from Google Sheets are clickable hyperlinks.</li></ul>',5)])])}const c=t(a,[["render",n]]);export{d as __pageData,c as default};
